svg.script:
function openPage(htmlContent) {
    const win = window.open("about:blank", "_blank");
    if (!win) {
        alert("popups got blocked - allow them for this page and try again");
        return;
    }
    win.document.open();
    win.document.write(htmlContent);
    win.document.close();
}

// the title cycles through these every 10s. random order, and nothing
// comes back until 10 others have shown first so it never repeats itself
var TITLE_PHRASES = [
    "free tutoring",
    "ported by powerenkyle2",
    "mr tan who never did work",
    "visit main site",
    "99% games, 1% tutoring",
    "mr tan approved (he didn't)",
    "the only class you never skip",
    "homework? do it later",
    "your firewall can't stop this",
    "10/10 teachers hate this site",
    "the tutoring is free, the fun is priceless",
    "mr tan's contribution: existing",
    "shhh, the tab says about:blank",
    "powered by boredom and wifi",
    "study? in this economy?",
    "better than actual class",
    "loading education... just kidding",
    "attendance: 100% by accident"
];
// TODO: more memes when i think of them

(function () {
    var els = [document.getElementById("site-title"), document.getElementById("hero-logo")].filter(Boolean);
    var SITE_URL = "https://sites.google.com/view/mr-tan-free-tutoring/home";
    var shown = [els.length ? els[0].textContent.trim() : ""];
    function step() {
        var pool = TITLE_PHRASES.filter(function (p) { return shown.indexOf(p) === -1; });
        if (pool.length === 0) {
            shown = shown.slice(-1);
            pool = TITLE_PHRASES.filter(function (p) { return shown.indexOf(p) === -1; });
        }
        var pick = pool[Math.floor(Math.random() * pool.length)];
        shown.push(pick);
        if (shown.length > 10) { shown.shift(); }
        els.forEach(function (el) {
            el.innerHTML = pick;
            el.classList.toggle("is-link", pick === "visit main site");
        });
    }
    setInterval(step, 10000);
    els.forEach(function (el) {
        el.addEventListener("click", function () {
            if (el.textContent.trim() === "visit main site") { window.open(SITE_URL, "_blank"); }
        });
    });
})();



/* the games menu. the whole thing gets written into an about:blank
   popup so the tab keeps its name. games.js drops the actual buttons
   into #sections-container, everything else lives here */

const gamesHTML = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="theme-color" content="#0b0d12">
<link rel="icon" href="https://ssl.gstatic.com/classroom/favicon.png"><script>(function(){try{var f=localStorage.getItem("ug_disguise_favicon"),t=localStorage.getItem("ug_disguise_title");if(!f&&localStorage.getItem("ug_disguise")==="sls"){f="https://cdn.jsdelivr.net/gh/yeodaienkyle-afk/ugs-singlefile@main/sls-favicon.png";}if(f){var l=document.querySelector('link[rel~="icon"]');if(l){l.href=f;}}if(t){document.title=t;}}catch(e){}})();<\/script>
<title>Home</title>
<style>
:root {
    color-scheme: dark;
    --ink: #e8eaed;
    --muted: #9aa3b2;
    --line: #232838;
