}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
    font-family: 'Segoe UI', Roboto, Arial, sans-serif;
    background: var(--bg);
    color: var(--ink);
}
.appbar {
    position: sticky; top: 0; z-index: 20;
    display: flex; align-items: center; gap: 12px;
    background: #0d1017;
    padding: 8px 16px;
    border-bottom: 1px solid var(--line);
}
.material {
    display: inline-flex; align-items: center; justify-content: center;
    width: 40px; height: 40px; border-radius: 50%; cursor: pointer; flex-shrink: 0;
    border: none; background: transparent;
}
.material:hover { background: #1c2130; }
svg.icon { width: 22px; height: 22px; fill: #9aa3b2; }
.hero {
    max-width: 1240px; margin: 24px auto 4px; padding: 0 20px;
    display: flex; align-items: center; justify-content: center; gap: 14px;
    flex-wrap: wrap;
}
.title-block { text-align: center; min-width: 0; }
.site-title {
    font-size: clamp(26px, 4.5vw, 42px);
    font-weight: 800;
    line-height: 1.2;
    background: linear-gradient(90deg, #ff5f6d, #ffc371, #f7ff47, #47f0a3, #4facfe, #a46bff, #ff5f6d);
    background-size: 300% 100%;
    -webkit-background-clip: text; background-clip: text; color: transparent;
    animation: rainbow-slide 6s linear infinite;
    filter: drop-shadow(0 0 14px rgba(164,107,255,.35));
    cursor: default; user-select: none;
    transition: filter .25s ease;
    display: inline-block;
    max-width: 100%;
}
.site-title.is-link { cursor: pointer; filter: drop-shadow(0 0 22px rgba(71,240,163,.65)); }
@keyframes rainbow-slide { to { background-position: 300% 0; } }
.credits {
    margin-top: 8px;
    font-size: 13px; color: var(--muted);
}
.gear-btn {
    display: inline-flex; align-items: center; justify-content: center;
    width: 38px; height: 38px; border-radius: 50%;
    border: 1px solid var(--line); background: transparent; cursor: pointer;
    flex-shrink: 0;
}
.gear-btn:hover { border-color: #a46bff; box-shadow: 0 0 12px rgba(164,107,255,.45); }
.gear-btn svg { width: 20px; height: 20px; fill: var(--muted); }
.settings-panel {
    position: fixed; top: 74px; right: 16px; z-index: 60;
    width: 240px;
    background: #12161f;
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 14px;
    box-shadow: 0 8px 30px rgba(0,0,0,.55);
    display: none;
}
.settings-panel.open { display: block; }
.settings-panel h3 { font-size: 13px; font-weight: 600; color: var(--muted); margin-bottom: 10px; text-transform: uppercase; letter-spacing: .8px; }
.set-row { margin-bottom: 12px; }
.set-label { font-size: 12px; color: var(--muted); margin-bottom: 6px; }
.seg { display: flex; gap: 6px; }
.seg button {
    flex: 1; height: 32px; border-radius: 8px;
    border: 1px solid var(--line); background: transparent;
    color: var(--muted); font-size: 12px; cursor: pointer;
}
.seg button.active { border-color: #a46bff; color: #fff; box-shadow: 0 0 10px rgba(164,107,255,.4); }
.toggle {
    width: 100%; height: 32px; border-radius: 8px;
    border: 1px solid var(--line); background: transparent;
    color: var(--muted); font-size: 12px; cursor: pointer;
}
.toggle.on { border-color: #47f0a3; color: #fff; box-shadow: 0 0 10px rgba(71,240,163,.35); }
body.noglow * { box-shadow: none !important; }
body.norotate .strip { animation: none !important; }
.set-input {
    width: 100%; height: 30px;
    background: #0d1017;
    border: 1px solid var(--line); border-radius: 8px;
    color: var(--ink); font-size: 12px;
    padding: 0 8px;
}
.set-input:focus { outline: none; border-color: #a46bff; }
.hide-btn {
    width: 100%; height: 34px;
    border: 1px solid rgba(255,95,109,.4); border-radius: 8px;
    color: #ff8a8a; background: transparent;
    font-size: 12px; font-weight: 600; letter-spacing: 1px;
    cursor: pointer;
}
.hide-btn:hover { background: rgba(255,95,109,.15); box-shadow: 0 0 12px rgba(255,95,109,.5); color: #fff; }
.toolbar {
    display: flex; align-items: center; gap: 14px;
    max-width: 1240px; margin: 18px auto 6px; padding: 0 20px;
    flex-wrap: wrap;
}
.search-glow {
    flex: 1; min-width: 220px; max-width: 560px;
    padding: 2px; border-radius: 27px;
    background: conic-gradient(from 0deg, #ff5f6d, #ffc371, #f7ff47, #47f0a3, #4facfe, #a46bff, #ff5f6d);
    animation: rainbow-spin 5s linear infinite;
    box-shadow: 0 0 18px rgba(164,107,255,.25);
}
@keyframes rainbow-spin { to { filter: hue-rotate(360deg); } }
.searchbox {
    height: 44px; border-radius: 25px;
    background: #12161f;
    display: flex; align-items: center; gap: 10px;
    padding: 0 16px;
}
.searchbox svg { fill: var(--muted); width: 20px; height: 20px; flex-shrink: 0; }
#searchInput {
    border: none; outline: none; background: transparent;
    font-size: 15px; color: var(--ink); width: 100%;
}
#searchInput::placeholder { color: #6b7385; }
#lolbutton {
    height: 38px; padding: 0 18px;
    border: 1px solid rgba(255,255,255,.14); border-radius: 19px;
    background: #12161f; color: #c9d2e0;
    font-size: 13px; font-weight: 500; cursor: pointer;
}
#lolbutton:hover { border-color: #a46bff; box-shadow: 0 0 12px rgba(164,107,255,.45); color: #fff; }
#game-count {
    height: 38px; padding: 0 16px;
    display: inline-flex; align-items: center;
    border: 1px solid var(--line); border-radius: 19px;
    background: #12161f;
    color: var(--muted); font-size: 12px;
    white-space: nowrap;
}
#sections-container { max-width: 1240px; margin: 0 auto; padding: 10px 20px 40px; }
.letter-section {
    background: transparent;
    margin-bottom: 26px;
    scroll-margin-top: 90px;
}
/* the A-Z rail on the right, games.js fills this in */
#sidebar {
    position: fixed;
    right: 6px; top: 50%;
    transform: translateY(-50%);
    z-index: 40;
    display: flex; flex-direction: column;
    gap: 2px;
    max-height: 78vh;
    overflow-y: auto;
    scrollbar-width: none;
    padding: 6px 4px;
    background: rgba(13,16,23,.85);
    border: 1px solid var(--line);
    border-radius: 10px;
}
#sidebar::-webkit-scrollbar { display: none; }
.sidebar-btn {
    border: none; background: transparent;
    color: var(--muted);
    font-size: 10px; font-weight: 600;
    width: 20px; height: 18px;
    border-radius: 5px;
    cursor: pointer;
    line-height: 1;
}
.sidebar-btn:hover {
    color: #fff;
    background: hsl(285 95% 60% / .25);
    box-shadow: 0 0 8px hsl(285 95% 60% / .45);
}
.sidebar-btn.empty { opacity: .25; pointer-events: none; }
.letter-header {
    display: inline-flex; align-items: center;
    min-height: 34px;
    padding: 2px 18px;
    border-radius: 10px;
    color: #fff;
    font-size: 17px; font-weight: 700;
    letter-spacing: .5px;
    margin-bottom: 12px;
    text-shadow: 0 0 10px rgba(255,255,255,.35);
}
#sections-container .letter-section:nth-of-type(7n+1) .letter-header { background: linear-gradient(135deg,#7986cb,#303f9f); }
#sections-container .letter-section:nth-of-type(7n+2) .letter-header { background: linear-gradient(135deg,#4285f4,#1a56d6); }
#sections-container .letter-section:nth-of-type(7n+3) .letter-header { background: linear-gradient(135deg,#34a853,#0d652d); }
#sections-container .letter-section:nth-of-type(7n+4) .letter-header { background: linear-gradient(135deg,#f9ab00,#e37400); }
#sections-container .letter-section:nth-of-type(7n+5) .letter-header { background: linear-gradient(135deg,#a142f4,#6f2db8); }
#sections-container .letter-section:nth-of-type(7n+6) .letter-header { background: linear-gradient(135deg,#26a69b,#00796b); }
#sections-container .letter-section:nth-of-type(7n+7) .letter-header { background: linear-gradient(135deg,#f28b82,#c5221f); }
.letter-section.empty { opacity: .55; }
.empty-message { color: var(--muted); font-style: italic; font-size: 13px; padding: 8px 0 4px; }
/* card view - the strips crawl sideways on their own */
.strip {
    display: flex; gap: 12px;
    overflow-x: auto;
    overflow-y: hidden;
    scroll-behavior: auto;
    padding: 4px 2px 10px;
    scrollbar-width: none;
}
.strip::-webkit-scrollbar { display: none; }
body.cardmode .strip { display: flex; }
body.listmode .strip { display: none; }
body.cardmode .buttons-container { display: none; }
body.listmode .buttons-container { display: grid; }
.gcard {
    flex: 0 0 196px;
    width: 196px;
    border-radius: 12px;
    background: var(--card);
    border: 1px solid hsl(var(--hue, 210) 95% 60% / .45);
    box-shadow: 0 0 10px hsl(var(--hue, 210) 95% 55% / .20);
    cursor: pointer;
    overflow: hidden;
    transition: box-shadow .18s ease, border-color .18s ease, transform .18s ease;
    user-select: none;
}
.gcard:hover {
    transform: translateY(-2px);
    border-color: hsl(var(--hue, 210) 95% 68%);
    box-shadow: 0 0 18px hsl(var(--hue, 210) 95% 55% / .6);
}
.gthumb {
    position: relative;
    width: 100%; height: 122px;
    background:
        linear-gradient(135deg, hsl(var(--hue, 210) 80% 22%), #171b26 70%),
        var(--card);
    overflow: hidden;
}
.gthumb img {
    position: absolute; inset: 0;
    width: 100%; height: 100%;
    object-fit: cover; object-position: top left;
    image-rendering: auto;
    display: none;
}
.gthumb img.loaded { display: block; }
.gthumb .ph {
    position: absolute; inset: 0;
    display: flex; align-items: center; justify-content: center;
    font-size: 34px; font-weight: 800;
    color: hsl(var(--hue, 210) 95% 70% / .85);
    text-shadow: 0 0 14px hsl(var(--hue, 210) 95% 60% / .5);
}
.gthumb img.loaded + .ph { display: none; }
.gmeta { padding: 8px 10px 10px; }
.gtitle {
    font-size: 13px; font-weight: 600;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    color: var(--ink);
}
.gdesc {
    margin-top: 3px;
    font-size: 11px;
    line-height: 1.35;
    color: var(--muted);
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    min-height: 30px;
}
@keyframes hue-flow { to { filter: hue-rotate(360deg); } }
/* list view - plain text, loads way faster */
.buttons-container {
    display: none;
    grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
    grid-auto-rows: 40px;
    gap: 9px;
}
body.listmode .buttons-container { display: grid; }
.buttons-container input[type="button"] {
    width: 100%; height: 100%;
    background: #12161f;
    border: 1px solid hsl(var(--hue, 210) 95% 60% / .55);
    border-radius: 10px;
    padding: 0 14px;
    font-size: 13px;
    color: var(--ink);
    text-align: left;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    cursor: pointer;
    --hue: 210;
    box-shadow: 0 0 7px hsl(var(--hue, 210) 95% 55% / .22);
    animation: hue-flow var(--dur, 18s) linear infinite;
    animation-delay: var(--del, 0s);
    transition: box-shadow .18s ease, background .18s ease, border-color .18s ease;
}
.buttons-container input[type="button"]:hover {
    background: hsl(var(--hue, 210) 90% 55% / .13);
    border-color: hsl(var(--hue, 210) 95% 68%);
    box-shadow: 0 0 16px hsl(var(--hue, 210) 95% 55% / .6);
}
/* little cards for the pinned + recent strips */
.gcard.mini { flex: 0 0 150px; width: 150px; }
.gcard.mini .gthumb { height: 92px; }
.gcard.mini .ph { font-size: 26px; }
.gcard.mini .gmeta { padding: 6px 8px 8px; }
.gcard.mini .gtitle { font-size: 12px; }
/* the pin button on each card */
.pinbtn {
    position: absolute; top: 6px; right: 6px; z-index: 2;
    width: 24px; height: 24px; border-radius: 50%;
    border: 1px solid rgba(255,255,255,.25);
    background: rgba(11,13,18,.65);
    font-size: 11px; line-height: 1;
    display: flex; align-items: center; justify-content: center;
    cursor: pointer; opacity: 0;
    transition: opacity .15s ease, border-color .15s ease;
}
.gcard:hover .pinbtn { opacity: 1; }
.pinbtn.on { opacity: 1; border-color: #ffc371; box-shadow: 0 0 10px rgba(255,195,113,.45); }
@media (hover: none) { .pinbtn { opacity: 1; } }
@media (max-width: 768px) {
    .gcard { flex-basis: 160px; width: 160px; }
    .gthumb { height: 100px; }
    .buttons-container { grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); }
}
@media (max-width: 1100px) {
    #sidebar { display: none; }
}
/* the orb - it lags behind the mouse on purpose so it sways */
* { cursor: none !important; }
#cursor-orb {
    position: fixed; left: 0; top: 0;
    width: 34px; height: 34px; margin: -17px 0 0 -17px;
    box-sizing: border-box;
    border-radius: 50%;
    background: hsl(210 95% 62% / 0.2);
    border: 2px solid hsl(210 95% 72% / 0.95);
    box-shadow: 0 0 14px hsl(210 95% 62% / 0.65), 0 0 36px hsl(285 95% 60% / 0.45);
    pointer-events: none;
    z-index: 2147483647;
    animation: orb-hue 5s linear infinite;
    will-change: transform;
}
@keyframes orb-hue { to { filter: hue-rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
    * { animation: none !important; transition: none !important; }
}
</style>
</head>
<body class="cardmode">

