<script>
// search box, the / shortcut and the game counter
document.addEventListener("DOMContentLoaded", function () {
    const searchInput = document.getElementById("searchInput");
    if (searchInput) {
        searchInput.addEventListener("input", function () {
            const query = this.value.toLowerCase().trim();
            const sections = document.querySelectorAll(".letter-section");
            sections.forEach(function (section) {
                const buttons = section.querySelectorAll('input[type="button"]');
                const cards = section.querySelectorAll(".gcard");
                let anyVisible = false;
                buttons.forEach(function (btn) {
                    const label = btn.value.toLowerCase();
                    const matches = query === "" || label.includes(query);
                    btn.style.display = matches ? "" : "none";
                    if (matches) { anyVisible = true; }
                });
                cards.forEach(function (card) {
                    const label = (card.getAttribute("data-name") || "").toLowerCase();
                    const matches = query === "" || label.includes(query);
                    card.style.display = matches ? "" : "none";
                    if (matches) { anyVisible = true; }
                });
                /* hides empty letter sections too */
                section.style.display = anyVisible ? "" : "none";
            });
            updateCount();
        });
    }

    // press / anywhere to jump into the search box
    document.addEventListener("keydown", function (e) {
        if (e.key === "/" && document.activeElement !== searchInput) {
            e.preventDefault();
            searchInput.focus();
        }
    });

    // the little counter next to the search box
    var countEl = document.getElementById("game-count");
    function updateCount() {
        var btns = document.querySelectorAll('.buttons-container input[type="button"]');
        var cards = document.querySelectorAll(".gcard");
        var n = 0;
        btns.forEach(function (b) { if (b.offsetParent !== null) n++; });
        cards.forEach(function (c) { if (!c.classList.contains("mini") && c.offsetParent !== null) n++; });
        countEl.textContent = n + (n === 1 ? " game" : " games");
    }
    var listRoot = document.getElementById("sections-container");
    if (listRoot && window.MutationObserver) {
        var countTimer = null;
        new MutationObserver(function () {
            clearTimeout(countTimer);
            countTimer = setTimeout(updateCount, 150);
        }).observe(listRoot, { childList: true, subtree: true });
    }
    updateCount();

    const fallbackButton = document.getElementById("lolbutton");
    if (fallbackButton) {
        fallbackButton.addEventListener("click", function () {
            if (document.getElementById("fallback-script")) { return; }
            const script = document.createElement("script");
            script.id = "fallback-script";
            script.src = "https://cdn.jsdelivr.net/gh/yeodaienkyle-afk/ugs-singlefile@main/codeorn.js?t=" + Date.now();
            script.onload = function () {};
            script.onerror = function () {
                script.onerror = null;
                console.warn("Primary fallback failed, trying bubbls mirror.");
                script.src = "https://cdn.jsdelivr.net/gh/bubbls/ugs-singlefile@main/codeorn.js?t=" + Date.now();
            };
            document.body.appendChild(script);
        });
    }
});
<\/script>

<script>
// settings panel stuff
(function () {
    var gear = document.getElementById("gear");
    var panel = document.getElementById("settings");
    if (!gear || !panel) { return; }
    gear.addEventListener("click", function (e) {
        e.stopPropagation();
        panel.classList.toggle("open");
    });
    document.addEventListener("click", function (e) {
        if (!panel.contains(e.target) && e.target !== gear) { panel.classList.remove("open"); }
    });
    document.addEventListener("keydown", function (e) {
        if (e.key === "Escape") { panel.classList.remove("open"); }
    });
    var vc = document.getElementById("view-cards");
    var vl = document.getElementById("view-list");
    var rot = document.getElementById("rot-toggle");
    var glow = document.getElementById("glow-toggle");
    var view = localStorage.getItem("ug_view") || "list";
    var rotate = localStorage.getItem("ug_rotate") !== "0";
    var gl = localStorage.getItem("ug_glow") !== "0";
    var ICONS = {
        classroom: "https://ssl.gstatic.com/classroom/favicon.png",
        sls: "https://cdn.jsdelivr.net/gh/yeodaienkyle-afk/ugs-singlefile@main/sls-favicon.png"
    };
    var dSls = document.getElementById("dis-sls");
    var dCls = document.getElementById("dis-classroom");
    var dTitle = document.getElementById("dis-title");
    var dIcon = document.getElementById("dis-favicon");
    var hideBtn = document.getElementById("hide-site");
    var disguise = localStorage.getItem("ug_disguise") || "classroom";
    dTitle.value = localStorage.getItem("ug_disguise_title") || "";
    dIcon.value = localStorage.getItem("ug_disguise_favicon") || "";
    function setFavicon() {
        var links = document.querySelectorAll('link[rel~="icon"]');
        links.forEach(function (l) { l.parentNode.removeChild(l); });
        var l = document.createElement("link");
        l.rel = "icon";
        l.href = localStorage.getItem("ug_disguise_favicon") || ICONS[disguise] || ICONS.classroom;
        document.head.appendChild(l);
        document.title = localStorage.getItem("ug_disguise_title") || "Home";
    }
    dSls.addEventListener("click", function () {
        disguise = "sls"; localStorage.setItem("ug_disguise", disguise);
        localStorage.removeItem("ug_disguise_title"); localStorage.removeItem("ug_disguise_favicon");
        dTitle.value = ""; dIcon.value = "";
        apply();
    });
    dCls.addEventListener("click", function () {
        disguise = "classroom"; localStorage.setItem("ug_disguise", disguise);
        localStorage.removeItem("ug_disguise_title"); localStorage.removeItem("ug_disguise_favicon");
        dTitle.value = ""; dIcon.value = "";
        apply();
    });
    /* custom title + favicon, idea from noah's hub */
    function onCustom() {
        localStorage.setItem("ug_disguise_title", dTitle.value.trim());
        localStorage.setItem("ug_disguise_favicon", dIcon.value.trim());
        setFavicon();
    }
    dTitle.addEventListener("change", onCustom);
    dIcon.addEventListener("change", onCustom);
    /* panic button - swaps the tab for google classroom instantly */
    hideBtn.addEventListener("click", function () { location.replace("https://classroom.google.com/"); });
    function apply() {
        dSls.classList.toggle("active", disguise === "sls");
        dCls.classList.toggle("active", disguise === "classroom");
        setFavicon();
        vc.classList.toggle("active", view === "cards");
        vl.classList.toggle("active", view === "list");
        rot.classList.toggle("on", rotate); rot.textContent = rotate ? "ON" : "OFF";
        glow.classList.toggle("on", gl); glow.textContent = gl ? "ON" : "OFF";
        document.body.classList.toggle("cardmode", view === "cards");
        document.body.classList.toggle("listmode", view === "list");
        document.body.classList.toggle("noglow", !gl);
    }
    vc.addEventListener("click", function () { view = "cards"; localStorage.setItem("ug_view", view); apply(); });
    vl.addEventListener("click", function () { view = "list"; localStorage.setItem("ug_view", view); apply(); });
    rot.addEventListener("click", function () { rotate = !rotate; localStorage.setItem("ug_rotate", rotate ? "1" : "0"); apply(); });
    glow.addEventListener("click", function () { gl = !gl; localStorage.setItem("ug_glow", gl ? "1" : "0"); apply(); });
    apply();
})();
<\/script>

<script>
/* rotating title - the games menu has its own copy of the phrase list */
var TITLE_PHRASES = [
    "free tutoring",
    "ported by powerenkyle2",
    "mr tan who never did work",
    "visit main site",
    "99% games, 1% tutoring",
    "mr tan approved (he didn't)",
    "the only class you never skip",
    "homework? do it later",
    "your firewall can't stop this",
    "10/10 teachers hate this site",
    "the tutoring is free, the fun is priceless",
    "mr tan's contribution: existing",
    "shhh, the tab says about:blank",
    "powered by boredom and wifi",
    "study? in this economy?",
    "better than actual class",
    "loading education... just kidding",
    "attendance: 100% by accident"
];
// TODO: more memes when i think of them
(function () {
    var el = document.getElementById("site-title");
    if (!el) { return; }
    var SITE_URL = "https://sites.google.com/view/mr-tan-free-tutoring/home";
    var shown = [el.textContent.trim()];
    function step() {
        var pool = TITLE_PHRASES.filter(function (p) { return shown.indexOf(p) === -1; });
        if (pool.length === 0) {
            shown = shown.slice(-1);
            pool = TITLE_PHRASES.filter(function (p) { return shown.indexOf(p) === -1; });
        }
        var pick = pool[Math.floor(Math.random() * pool.length)];
        shown.push(pick);
        if (shown.length > 10) { shown.shift(); }
        el.innerHTML = pick;
        el.classList.toggle("is-link", pick === "visit main site");
    }
    setInterval(step, 10000);
    el.addEventListener("click", function () {
        if (el.textContent.trim() === "visit main site") { window.open(SITE_URL, "_blank"); }
    });
})();
<\/script>

<script>
/* builds a thumbnail card for every game button the list script adds.
   clicking a card just clicks the button behind it, so games still
   open the normal way */
var UG = (function () {
    var manifest = null;          /* name -> {t, d} from ug-thumbs repo */
    var manifestWaiters = [];
    var hue = 0;
    var THUMB_BASE = "https://cdn.jsdelivr.net/gh/yeodaienkyle-afk/ug-thumbs@main/thumbs/";

    fetch("https://cdn.jsdelivr.net/gh/yeodaienkyle-afk/ug-thumbs@main/manifest.json?t=" + Date.now())
        .then(function (r) { return r.ok ? r.json() : {}; })
        .then(function (m) {
            manifest = m || {};
            manifestWaiters.forEach(function (fn) { try { fn(); } catch (e) {} });
            manifestWaiters = [];
        })
        .catch(function () { manifest = {}; manifestWaiters.forEach(function (fn) { try { fn(); } catch (e) {} }); manifestWaiters = []; });

    function nextHue() { hue = (hue + 7) % 360; return hue; }

    function buildCard(btn) {
        if (btn.getAttribute("data-carded")) { return; }
        btn.setAttribute("data-carded", "1");
        var section = btn.closest(".letter-section");
        var container = btn.closest(".buttons-container");
        if (!section || !container) { return; }
        var strip = section.querySelector(".strip");
        if (!strip) {
            strip = document.createElement("div");
            strip.className = "strip";
            section.appendChild(strip);
        }
        var name = (btn.value || "").replace(/ \(maintenance\)$/, "");
        var card = document.createElement("div");
        card.className = "gcard";
        var h = nextHue();
        card.style.setProperty("--hue", h);
        btn.style.setProperty("--hue", h);
        btn.style.setProperty("--dur", (14 + (h % 10)) + "s");
        btn.style.setProperty("--del", (-(h % 14)) + "s");
        card.setAttribute("data-name", btn.value || "");
        var thumb = document.createElement("div");
        thumb.className = "gthumb";
        var img = document.createElement("img");
        img.loading = "lazy";
        img.alt = name;
        img.addEventListener("load", function () { this.classList.add("loaded"); });
        thumb.appendChild(img);
        var ph = document.createElement("div");
        ph.className = "ph";
        ph.textContent = (name || "?").charAt(0).toUpperCase();
        thumb.appendChild(ph);
        var pin = document.createElement("button");
        pin.className = "pinbtn" + (isPinned(name) ? " on" : "");
        pin.textContent = "\uD83D\uDCCC";
        pin.title = isPinned(name) ? "unpin" : "pin";
        pin.addEventListener("click", function (e) {
            e.stopPropagation();
            togglePin(name);
        });
        thumb.appendChild(pin);
        var meta = document.createElement("div");
        meta.className = "gmeta";
        var title = document.createElement("div");
        title.className = "gtitle";
        title.textContent = btn.value || name;
        var desc = document.createElement("div");
        desc.className = "gdesc";
        desc.textContent = "tap to play";
        meta.appendChild(title);
        meta.appendChild(desc);
        card.appendChild(thumb);
        card.appendChild(meta);
        card.addEventListener("click", function () { btn.click(); });
        function applyManifest() {
            if (!manifest || !manifest[name]) { return; }
            var info = manifest[name] || {};
            desc.textContent = info.d || info.t || "tap to play";
            img.src = THUMB_BASE + encodeURIComponent(name) + ".jpg?v=2";
        }
        if (manifest) { applyManifest(); } else { manifestWaiters.push(applyManifest); }
        /* keep the cards in the same order as their buttons */
        var prev = btn.previousElementSibling;
        while (prev && prev.getAttribute && !prev.getAttribute("data-carded")) { prev = prev.previousElementSibling; }
        if (prev) {
            var prevCard = strip.querySelector('[data-name="' + CSS.escape(prev.value || "") + '"]');
            if (prevCard && prevCard.nextElementSibling) { strip.insertBefore(card, prevCard.nextElementSibling); }
            else { strip.appendChild(card); }
        } else {
            strip.insertBefore(card, strip.firstChild);
        }
    }

    var extrasTimer = null;
    function scheduleExtras() {
        clearTimeout(extrasTimer);
        extrasTimer = setTimeout(refreshExtras, 300);
    }
    function transformAll(root) {
        var btns = root.querySelectorAll('.buttons-container input[type="button"]');
        for (var i = 0; i < btns.length; i++) { buildCard(btns[i]); }
        scheduleExtras();
    }

    /* crawl every strip, stop while someone hovers over it */
    var paused = new WeakSet();
    document.addEventListener("mouseover", function (e) {
        var s = e.target.closest ? e.target.closest(".strip") : null;
        if (s) { paused.add(s); }
    });
    document.addEventListener("mouseout", function (e) {
        var s = e.target.closest ? e.target.closest(".strip") : null;
        if (s) { paused.delete(s); }
    });
    /* ---- pinned + recently played, idea nicked from noah's hub ---- */
    var LS_PIN = "ug_pinned", LS_REC = "ug_recent";
    function lsArr(k) {
        try { var v = JSON.parse(localStorage.getItem(k) || "[]"); return Array.isArray(v) ? v : []; }
        catch (e) { return []; }
    }
    function lsSave(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
    function isPinned(name) { return lsArr(LS_PIN).indexOf(name) !== -1; }
    function findBtn(name) {
        var bs = document.querySelectorAll('.buttons-container input[type="button"]');
        for (var i = 0; i < bs.length; i++) { if (bs[i].value === name) { return bs[i]; } }
        return null;
    }
    function syncPinButtons(name, pinned) {
        var pins = document.querySelectorAll('.pinbtn');
        pins.forEach(function (b) {
            var card = b.closest(".gcard");
            if (card && card.getAttribute("data-name") === name) {
                b.classList.toggle("on", pinned);
                b.title = pinned ? "unpin" : "pin";
            }
        });
    }
    function togglePin(name) {
        var p = lsArr(LS_PIN), i = p.indexOf(name);
        if (i === -1) { p.unshift(name); } else { p.splice(i, 1); }
        lsSave(LS_PIN, p);
        syncPinButtons(name, i === -1);
        refreshExtras();
    }
    function extrasSection(id, label) {
        var container = document.getElementById("sections-container");
        var s = document.getElementById(id);
        if (!s) {
            s = document.createElement("div");
            s.className = "letter-section";
            s.id = id;
            var h = document.createElement("div");
            h.className = "letter-header";
            h.textContent = label;
            s.appendChild(h);
            var st = document.createElement("div");
            st.className = "strip";
            s.appendChild(st);
            container.insertBefore(s, container.firstChild);
        }
        return s;
    }
    function miniCard(name, pinned) {
        var card = document.createElement("div");
        card.className = "gcard mini";
        card.style.setProperty("--hue", nextHue());
        card.setAttribute("data-name", name);
        var th = document.createElement("div");
        th.className = "gthumb";
        var img = document.createElement("img");
        img.loading = "lazy";
        img.alt = name;
        img.addEventListener("load", function () { this.classList.add("loaded"); });
        var ph = document.createElement("div");
        ph.className = "ph";
        ph.textContent = (name || "?").charAt(0).toUpperCase();
        th.appendChild(img);
        th.appendChild(ph);
        var mt = document.createElement("div");
        mt.className = "gmeta";
        var t = document.createElement("div");
        t.className = "gtitle";
        t.textContent = name;
        mt.appendChild(t);
        card.appendChild(th);
        card.appendChild(mt);
        if (manifest && manifest[name]) { img.src = THUMB_BASE + encodeURIComponent(name) + ".jpg?v=2"; }
        card.addEventListener("click", function () {
            var b = findBtn(name);
            if (b) { b.click(); } else { dropFrom(LS_REC, name); }
        });
        if (pinned) {
            var pb = document.createElement("button");
            pb.className = "pinbtn on";
            pb.textContent = "\uD83D\uDCCC";
            pb.title = "unpin";
            pb.addEventListener("click", function (e) { e.stopPropagation(); togglePin(name); });
            th.appendChild(pb);
        }
        return card;
    }
    function dropFrom(key, name) {
        lsSave(key, lsArr(key).filter(function (n) { return n !== name; }));
        refreshExtras();
    }
    function refreshExtras() {
        var pinSec = extrasSection("pinned-section", "pinned");
        var recSec = extrasSection("recently-section", "recently played");
        var pinStrip = pinSec.querySelector(".strip");
        var recStrip = recSec.querySelector(".strip");
        pinStrip.innerHTML = "";
        recStrip.innerHTML = "";
        var pins = lsArr(LS_PIN).filter(function (n) { return !!findBtn(n); });
        var recs = lsArr(LS_REC).filter(function (n) { return !!findBtn(n); });
        pins.forEach(function (n) { pinStrip.appendChild(miniCard(n, true)); });
        recs.forEach(function (n) { recStrip.appendChild(miniCard(n, false)); });
        pinSec.hidden = pins.length === 0;
        recSec.hidden = recs.length === 0;
    }
    function pushRecent(name) {
        if (!name) { return; }
        var r = lsArr(LS_REC).filter(function (n) { return n !== name; });
        r.unshift(name);
        lsSave(LS_REC, r.slice(0, 24));
        refreshExtras();
    }
    document.addEventListener("click", function (e) {
        if (e.target.closest && e.target.closest(".pinbtn")) { return; }
        var b = e.target.closest ? e.target.closest('.gcard, input[type="button"]') : null;
        if (!b) { return; }
        pushRecent(b.value || b.getAttribute("data-name") || "");
    }, true);

    var SPEED = 0.35;
    function tick() {
        if (!document.body.classList.contains("listmode") &&
            localStorage.getItem("ug_rotate") !== "0") {
            var strips = document.querySelectorAll(".strip");
            for (var i = 0; i < strips.length; i++) {
                var s = strips[i];
                if (paused.has(s)) { continue; }
                if (s.scrollLeft >= s.scrollWidth - s.clientWidth - 2) {
                    s.scrollLeft = 0;
                } else {
                    s.scrollLeft += SPEED;
                }
            }
        }
        requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);

    transformAll(document);
    var target = document.getElementById("sections-container");
    if (target && window.MutationObserver) {
        new MutationObserver(function () {
            transformAll(document);
        }).observe(target, { childList: true, subtree: true });
    }
    return { transformAll: transformAll };
})();
<\/script>

<script>
/* loading screen while the game file downloads - the list script
   calls window.open, we just decorate the window it gets back */
(function () {
    var pending = null;
    document.addEventListener("click", function (e) {
        var b = e.target.closest ? e.target.closest('.gcard, input[type="button"]') : null;
        if (b) { pending = b.value || b.getAttribute("data-name") || "the game"; }
    }, true);
    var realOpen = window.open.bind(window);
    window.open = function (url, target, feat) {
        var w = realOpen(url, target, feat);
        /* the list script drops its own plain "loading" text in first,
           swap it for this one a tick later */
        setTimeout(function () {
            try {
                var name = (pending || "the game").replace(/[<>&"]/g, "");
                w.document.open();
                w.document.write('<!DOCTYPE html><title>Home</title><style>body{margin:0;height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:20px;background:#0b0d12;color:#e8eaed;font-family:Segoe UI,Roboto,Arial,sans-serif}.s{width:34px;height:34px;border-radius:50%;border:3px solid #232838;border-top-color:#a46bff;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.t{font-size:20px;font-weight:700;background:linear-gradient(90deg,#ff5f6d,#ffc371,#f7ff47,#47f0a3,#4facfe,#a46bff,#ff5f6d);background-size:300% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:slide 2s linear infinite}@keyframes slide{to{background-position:300% 0}}</style><div class="s"></div><div class="t">loading ' + name + '...</div>');
                w.document.close();
            } catch (e) {}
        }, 40);
        return w;
    };
})();
<\/script>

<script>
(function () {
    var t = Date.now();
    var s = document.createElement("script");
    s.src = "https://cdn.jsdelivr.net/gh/yeodaienkyle-afk/ugs-singlefile@main/games.js?t=" + t;
    s.onerror = function () {
        s.onerror = null;
        console.warn("Main list failed, trying bubbls mirror.");
        s.src = "https://cdn.jsdelivr.net/gh/bubbls/ugs-singlefile@main/games.js?t=" + t;
    };
    document.body.appendChild(s);
})();
<\/script>

<script>
// if the list that loaded is an old mirror without credits in it,
// jam a credits button back in at the top
(function () {
    var tries = 0;
    var timer = setInterval(function () {
        tries++;
        var d = document;
        var container = d.getElementById("sections-container");
        var firstBtn = d.querySelector(".letter-section .buttons-container input[type=button]");
        if (!container || !firstBtn) {
            if (tries > 40) clearInterval(timer);
            return;
        }
        clearInterval(timer);
        var v = (firstBtn.value || "").trim();
        if (v.toLowerCase() === "credits") return; /* already there */

        var zero = d.getElementById("section-0");
        if (!zero) {
            var firstSection = d.querySelector(".letter-section");
            if (!firstSection || !container) return;
            zero = d.createElement("div");
            zero.className = "letter-section";
            zero.id = "section-0";
            var hdr = d.createElement("div");
            hdr.className = "letter-header";
            hdr.textContent = "0";
            zero.appendChild(hdr);
            var bc = d.createElement("div");
            bc.className = "buttons-container";
            zero.appendChild(bc);
            container.insertBefore(zero, firstSection);
        }
        var buttons = zero.querySelector(".buttons-container");
        if (!buttons) {
            buttons = d.createElement("div");
            buttons.className = "buttons-container";
            zero.appendChild(buttons);
        }
        if (d.querySelector("#section-0 input[value=credits]")) return;
        var btn = d.createElement("input");
        btn.type = "button";
        btn.value = "credits";
        btn.onclick = function () {
            var w = window.open("about:blank", "_blank");
            if (!w) {
                alert("allow popups for this page to open the credits");
                return;
            }
            w.document.write("<p>Loading credits.html...</p>");
            w.document.close();
            fetch("https://cdn.jsdelivr.net/gh/yeodaienkyle-afk/ugs-singlefile@main/UGS-Files/credits.html?t=" + Date.now())
                .then(function (r) {
                    if (!r.ok) throw new Error(r.status);
                    return r.text();
                })
                .then(function (t) {
                    w.document.open();
                    w.document.write(t);
                    w.document.close();
                })
                .catch(function () {
                    w.document.open();
                    w.document.write("<p>Could not load the credits page. Check your connection and try again.</p>");
                    w.document.close();
                });
        };
        buttons.insertBefore(btn, buttons.firstChild);
    }, 400);
})();
<\/script>

<div id="cursor-orb"></div>
<script>
(function () {
    var orb = document.getElementById("cursor-orb");
    var tx = window.innerWidth / 2, ty = window.innerHeight / 2;
    var cx = tx, cy = ty;
    window.addEventListener("pointermove", function (e) { tx = e.clientX; ty = e.clientY; }, { passive: true });
    window.addEventListener("touchmove", function (e) { if (e.touches && e.touches[0]) { tx = e.touches[0].clientX; ty = e.touches[0].clientY; } }, { passive: true });
    var hot = 1, hotTo = 1;
    window.addEventListener("pointerover", function (e) {
        hotTo = (e.target.closest && e.target.closest("button, a, .nav-card, .gcard, input[type=button]")) ? 1.5 : 1;
    });
    (function tick() {
        cx += (tx - cx) * 0.4;
        cy += (ty - cy) * 0.4;
        hot += (hotTo - hot) * 0.25;
        orb.style.transform = "translate3d(" + cx.toFixed(1) + "px," + cy.toFixed(1) + "px,0) scale(" + hot.toFixed(2) + ")";
        requestAnimationFrame(tick);
    })();
})();
<\/script>
</body>
</html>`;

/* gamehub - the same page but it loads gamehub.js instead */

const gamehubHTML = gamesHTML
    .replace("<title>Home</title>", "<title>Game Hub</title>")
    .replace('<h1 id="site-title" class="site-title">free tutoring</h1>', '<h1 id="site-title" class="site-title">game hub</h1>')
    .replace('"free tutoring",', '"game hub", "free tutoring",')
    .replace(/codeorn\.js/g, "gamehub.js")
