<script>

(function () {

    var sky =
        document.getElementById('sky');

    var count = 220;

    for (var i = 0; i < count; i++) {

        var star =
            document.createElement('div');

        star.className = 'star';

        var size =
            Math.random() * 1.8 + 0.5;

        var top =
            Math.random() * 65;

        var left =
            Math.random() * 100;

        var duration =
            (Math.random() * 3 + 2).toFixed(2);

        var delay =
            (Math.random() * 5).toFixed(2);

        var minOp =
            (Math.random() * 0.3 + 0.1).toFixed(2);

        var maxOp =
            (Math.random() * 0.4 + 0.6).toFixed(2);

        star.style.width =
            size + 'px';

        star.style.height =
            size + 'px';

        star.style.top =
            top + '%';

        star.style.left =
            left + '%';

        star.style.setProperty(
            '--min-op',
            minOp
        );

        star.style.setProperty(
            '--max-op',
            maxOp
        );

        star.style.animationDuration =
            duration + 's';

        star.style.animationDelay =
            delay + 's';

        if (size > 1.6) {

            star.style.boxShadow =
                '0 0 ' +
                (size * 2) +
                'px rgba(255,255,255,0.6)';

        }

        sky.appendChild(star);

    }

})();

<\/script>

<div id="cursor-orb"></div>
<script>
(function () {
    var orb = document.getElementById("cursor-orb");
    var tx = window.innerWidth / 2, ty = window.innerHeight / 2;
    var cx = tx, cy = ty;
    window.addEventListener("pointermove", function (e) { tx = e.clientX; ty = e.clientY; }, { passive: true });
    window.addEventListener("touchmove", function (e) { if (e.touches && e.touches[0]) { tx = e.touches[0].clientX; ty = e.touches[0].clientY; } }, { passive: true });
    var hot = 1, hotTo = 1;
    window.addEventListener("pointerover", function (e) {
        hotTo = (e.target.closest && e.target.closest("button, a, .nav-card, .gcard, input[type=button]")) ? 1.5 : 1;
    });
    (function tick() {
        cx += (tx - cx) * 0.4;
        cy += (ty - cy) * 0.4;
        hot += (hotTo - hot) * 0.25;
        orb.style.transform = "translate3d(" + cx.toFixed(1) + "px," + cy.toFixed(1) + "px,0) scale(" + hot.toFixed(2) + ")";
        requestAnimationFrame(tick);
    })();
})();
<\/script>
</body>
</html>`;

