<div class="wrap">
    <h1>contact</h1>
    <p class="arcade">&gt; INSERT MESSAGE TO SEND &lt;</p>
    <form class="form-card" id="cform" method="POST" action="https://script.google.com/a/macros/students.edu.sg/s/AKfycbwnC76NIeF57SnXAgL2me-l92MRvsbRbajf76wj5lOCliEdVNo0stU1_6txJaH3L_6l.exec" target="sendframe">
        <label for="cname">name</label>
        <input type="text" id="cname" name="name" placeholder="your name (or don't)">
        <label for="cmsg">message</label>
        <textarea id="cmsg" name="message" placeholder="broken game? game request? project idea? type it here" required></textarea>
        <button class="send" type="submit">SEND IT &#9656;</button>
        <div id="sent">fired off. if you're not signed into your school account it probably bounced tho</div>
    </form>
    <p class="note">goes through the school's form script. if it acts up, <a href="https://script.google.com/a/macros/students.edu.sg/s/AKfycbwnC76NIeF57SnXAgL2me-l92MRvsbRbajf76wj5lOCliEdVNo0stU1_6txJaH3L_6l.exec" target="_blank" rel="noopener">open the form in a new tab</a> instead.</p>
</div>
<iframe name="sendframe" id="sendframe" style="display:none"></iframe>
<div id="cursor-orb"></div>
<script>
(function () {
    var f = document.getElementById("cform");
    var sent = document.getElementById("sent");
    f.addEventListener("submit", function () {
        sent.style.display = "block";
        setTimeout(function () { f.reset(); }, 400);
    });
})();
<\/script>
<script>
(function () {
    var orb = document.getElementById("cursor-orb");
    var tx = window.innerWidth / 2, ty = window.innerHeight / 2;
    var cx = tx, cy = ty;
    window.addEventListener("pointermove", function (e) { tx = e.clientX; ty = e.clientY; }, { passive: true });
    window.addEventListener("touchmove", function (e) { if (e.touches && e.touches[0]) { tx = e.touches[0].clientX; ty = e.touches[0].clientY; } }, { passive: true });
    var hot = 1, hotTo = 1;
    window.addEventListener("pointerover", function (e) {
        hotTo = (e.target.closest && e.target.closest("button, a, .nav-card, .gcard, input[type=button]")) ? 1.5 : 1;
    });
    (function tick() {
        cx += (tx - cx) * 0.4;
        cy += (ty - cy) * 0.4;
        hot += (hotTo - hot) * 0.25;
        orb.style.transform = "translate3d(" + cx.toFixed(1) + "px," + cy.toFixed(1) + "px,0) scale(" + hot.toFixed(2) + ")";
        requestAnimationFrame(tick);
    })();
})();
<\/script>
</body>
</html>`;

(function () {
    var orb = document.getElementById("cursor-orb");
    var tx = window.innerWidth / 2, ty = window.innerHeight / 2;
    var cx = tx, cy = ty;
    window.addEventListener("pointermove", function (e) { tx = e.clientX; ty = e.clientY; }, { passive: true });
    window.addEventListener("touchmove", function (e) { if (e.touches && e.touches[0]) { tx = e.touches[0].clientX; ty = e.touches[0].clientY; } }, { passive: true });
    var hot = 1, hotTo = 1;
    window.addEventListener("pointerover", function (e) {
        hotTo = (e.target.closest && e.target.closest("button, a, .nav-card, .gcard, input[type=button]")) ? 1.5 : 1;
    });
    (function tick() {
        cx += (tx - cx) * 0.4;
        cy += (ty - cy) * 0.4;
        hot += (hotTo - hot) * 0.25;
        orb.style.transform = "translate3d(" + cx.toFixed(1) + "px," + cy.toFixed(1) + "px,0) scale(" + hot.toFixed(2) + ")";
        requestAnimationFrame(tick);
    })();
})();
